#include <renderer/electron_cloud_renderer.hpp>

#include <rlog.h>

#include <sokol_gfx.h>

#include <vulkan/vulkan.h>

#include <array>
#include <cmath>
#include <cstdint>

// Generated by build.cpp from shaders/electron_cloud.glsl.
#include "electron_cloud.glsl.h"

namespace renderer {

namespace {

// Written by build.cpp's nvcc step; relative to the project root, where ./run starts us.
constexpr const char* kPtxPath = ".build/cuda/electron_cloud_renderer.ptx";

constexpr sg_pixel_format kOutputFormat = SG_PIXELFORMAT_RGBA8;
constexpr u32 kBlock = 16; // 16 x 16 threads per CUDA block

void store3(float out[3], const Eigen::Vector3f& v) {
    out[0] = v.x();
    out[1] = v.y();
    out[2] = v.z();
}

} // namespace

ElectronCloudRenderer::ElectronCloudRenderer(RaymarchSettings settings)
    : m_settings(settings),
      m_copy(graphics::primitives::pass::FullscreenPass::create(ec_pixels_shader_desc(sg_query_backend()), kOutputFormat, "electron cloud copy")) {
    // Makes a context current on this (the render) thread, on sokol's GPU.
    m_cuda = gpu::CudaInterop::create();
    if (!m_cuda) {
        RLOG(LL_ERROR, "ElectronCloudRenderer: CUDA interop failed to start");
        return;
    }

    CUdevice device = 0;
    std::array<char, 256> name{};
    cuCtxGetDevice(&device);
    cuDeviceGetName(name.data(), static_cast<int>(name.size()), device);
    RLOG(LL_INFO, "ElectronCloudRenderer: CUDA on %s", name.data());

    if (cuModuleLoad(&m_module, kPtxPath) != CUDA_SUCCESS || cuModuleGetFunction(&m_raymarch, m_module, "raymarch") != CUDA_SUCCESS) {
        RLOG(LL_ERROR, "ElectronCloudRenderer: failed to load %s", kPtxPath);
        return;
    }

    m_cuda_done = gpu::CrossSemaphore::create("electron cloud cuda done");
    m_render_done = gpu::CrossSemaphore::create("electron cloud render done");
    if (!m_cuda_done || !m_render_done) {
        RLOG(LL_ERROR, "ElectronCloudRenderer: failed to create the cross-API semaphores");
        return;
    }
    m_cuda_done_sem = m_cuda->importSemaphore(*m_cuda_done);
    m_render_done_sem = m_cuda->importSemaphore(*m_render_done);
    if (m_cuda_done_sem < 0 || m_render_done_sem < 0) {
        RLOG(LL_ERROR, "ElectronCloudRenderer: failed to import the semaphores into CUDA");
        return;
    }

    m_ready = true;
}

ElectronCloudRenderer::~ElectronCloudRenderer() {
    waitIdle();
    // CUDA first: its imports of the pixel buffer and semaphores go before the Vulkan objects.
    if (m_module != nullptr) {
        cuModuleUnload(m_module);
    }
    m_cuda.reset();
}

void ElectronCloudRenderer::waitIdle() {
    if (m_cuda) {
        m_cuda->sync();
    }
    // The empty queueWait/queueSignal submits reference the semaphores, and the copy pass
    // reads the buffer: the graphics queue must drain before either is destroyed.
    if (sg_isvalid()) {
        const sg_vk_device_info dev = sg_vk_query_device_info();
        if (dev.device != 0) {
            vkDeviceWaitIdle(reinterpret_cast<VkDevice>(static_cast<uintptr_t>(dev.device)));
        }
    }
}

void ElectronCloudRenderer::beginFrame(const graphics::primitives::scene::Camera& camera) {
    const Eigen::Vector3f world_up{0.0f, 1.0f, 0.0f};
    const Eigen::Vector3f forward = camera.direction().normalized();
    const Eigen::Vector3f right = forward.cross(world_up).normalized();
    const Eigen::Vector3f up = right.cross(forward);

    RayCamera& out = m_params.camera;
    store3(out.position, camera.position());
    store3(out.forward, forward);
    store3(out.right, right);
    store3(out.up, up);
    // Camera keeps its vertical fov private; the projection's [1][1] is 1 / tan(fov_y / 2).
    out.tan_half_fov_y = 1.0f / camera.projectionMatrix()(1, 1);
    out.aspect = camera.aspectRatio();
}

void ElectronCloudRenderer::submit(const Sphere& sphere) {
    store3(m_params.sphere.center, sphere.center);
    m_params.sphere.radius = sphere.radius;
}

bool ElectronCloudRenderer::rebuildTargets(int width, int height) {
    // The old buffer may still be in use by CUDA or the last frame's copy.
    waitIdle();

    m_width = width;
    m_height = height;
    m_pixels_view = nullptr;
    m_pixels_cuda = 0;

    // Note: CudaInterop has no unmap, so on a resize the old buffer's CUDA import lives on
    // until the renderer is destroyed. The window is a fixed size, so this happens once.
    m_pixels = gpu::ExternalBuffer::create(static_cast<usize>(width) * static_cast<usize>(height) * sizeof(u32), "electron cloud pixels");
    if (!m_pixels) {
        RLOG(LL_ERROR, "ElectronCloudRenderer: failed to create the pixel buffer");
        return false;
    }
    m_pixels_cuda = m_cuda->mapBuffer(*m_pixels);
    if (m_pixels_cuda == 0) {
        RLOG(LL_ERROR, "ElectronCloudRenderer: failed to map the pixel buffer into CUDA");
        return false;
    }

    sg_view_desc view_desc = {};
    view_desc.storage_buffer.buffer = m_pixels->buffer();
    view_desc.label = "electron cloud pixels view";
    m_pixels_view = gpu::makeView(view_desc);

    m_target = graphics::primitives::pass::makeColorTarget(width, height, kOutputFormat, "electron cloud target");
    return true;
}

sg_view ElectronCloudRenderer::render(int width, int height) {
    if (!m_ready || width <= 0 || height <= 0) {
        return sg_view{};
    }
    if (width != m_width || height != m_height) {
        if (!rebuildTargets(width, height)) {
            m_ready = false;
            return sg_view{};
        }
    }

    // The previous frame's copy was submitted by sg_commit(), after the last render() returned.
    // This empty submit lands behind it on the queue, so it marks that copy as finished.
    if (m_frame > 0) {
        m_render_done->queueSignal(m_frame);
    }
    m_frame++;

    // CUDA: wait until the previous frame has finished reading the pixels, march, signal.
    m_params.step = m_settings.step;
    m_params.max_distance = m_settings.max_distance;
    m_params.width = static_cast<unsigned>(width);
    m_params.height = static_cast<unsigned>(height);

    CUstream stream = m_cuda->stream();
    m_cuda->waitAsync(m_render_done_sem, m_frame - 1, stream);
    void* args[] = {&m_pixels_cuda, &m_params};
    const u32 grid_x = (static_cast<u32>(width) + kBlock - 1) / kBlock;
    const u32 grid_y = (static_cast<u32>(height) + kBlock - 1) / kBlock;
    if (cuLaunchKernel(m_raymarch, grid_x, grid_y, 1, kBlock, kBlock, 1, 0, stream, args, nullptr) != CUDA_SUCCESS) {
        RLOG(LL_ERROR, "ElectronCloudRenderer: raymarch launch failed");
    }
    m_cuda->signalAsync(m_cuda_done_sem, m_frame, stream);

    // Graphics queue: hold the copy until CUDA has written this frame's pixels.
    m_cuda_done->queueWait(m_frame, VK_PIPELINE_STAGE_FRAGMENT_SHADER_BIT);

    sg_pass pass = {};
    pass.action.colors[0].load_action = SG_LOADACTION_DONTCARE;
    pass.attachments.colors[0] = *m_target.attachment;
    pass.label = "electron cloud copy pass";
    sg_begin_pass(&pass);

    sg_bindings bindings = {};
    bindings.views[VIEW_ec_pixels] = *m_pixels_view;
    m_copy.draw(bindings, [&]() {
        ec_pixels_params_t params = {};
        params.size[0] = static_cast<f32>(width);
        params.size[1] = static_cast<f32>(height);
        const sg_range range{&params, sizeof(params)};
        sg_apply_uniforms(UB_ec_pixels_params, &range);
    });

    sg_end_pass();

    return *m_target.texture;
}

} // namespace renderer
